function normalizeQuakes(data){if(!Array.isArray(data.features))throw Error('Invalid earthquakes');return data.features.filter(f=>f.geometry?.type==='Point'&&Number.isFinite(f.properties?.mag)&&f.properties.mag>=2.5&&Number.isFinite(f.properties.time)&&Date.now()-f.properties.time<=86400000).map(f=>({kind:'quake',id:f.id,lat:f.geometry.coordinates[1],lon:f.geometry.coordinates[0],depth:f.geometry.coordinates[2],mag:f.properties.mag,magType:f.properties.magType,title:f.properties.place||'未命名地震',date:f.properties.time,url:f.properties.url})).filter(valid)}
