function color(speed){const stops=[[0,43,88,193],[10,56,199,223],[20,88,223,144],[40,234,224,65],[60,240,124,56],[90,205,65,106]];let i=0;while(i<stops.length-2&&speed>stops[i+1][0])i++;const a=stops[i],b=stops[i+1],t=Math.max(0,Math.min(1,(speed-a[0])/(b[0]-a[0])));return a.slice(1).map((v,j)=>Math.round(v+(b[j+1]-v)*t))}
window.drawWindLayer=function(){if(!enabled||(!field&&!globalField)||!get('#windHeat').checked)return;const signature=[lat,lng,radius(),w,h,fieldVersion].join('|');if(signature!==textureSignature){textureSignature=signature;const image=tc.createImageData(texture.width,texture.height);for(let y=0;y<texture.height;y++)for(let x=0;x<texture.width;x++){const point=inverse((x+.5)/texture.width*w,(y+.5)/texture.height*h),value=point&&sample(point.lat,point.lon);if(!value)continue;const i=(y*texture.width+x)*4,c=color(value.speed);image.data[i]=c[0];image.data[i+1]=c[1];image.data[i+2]=c[2];image.data[i+3]=Math.round(255*(value.coverage??1))}tc.putImageData(image,0,0)}ctx.save();ctx.globalAlpha=.38;ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(texture,0,0,w,h);ctx.restore()};
