function frame(t){requestAnimationFrame(frame);if(document.hidden||!enabled||(!field&&!globalField)||!get('#windParticles').checked){if(particles.length){pc.clearRect(0,0,particleCanvas.width,particleCanvas.height);particles=[]}lastFrame=t;return}if(t-lastFrame<45)return;const dt=Math.min(.08,(t-lastFrame)/1000);lastFrame=t;const signature=[lat,lng,radius(),w,h,fieldVersion].join('|');if(signature!==viewSignature||!particles.length){viewSignature=signature;resetParticles()}pc.save();pc.globalCompositeOperation='destination-in';pc.fillStyle='rgba(0,0,0,.88)';pc.fillRect(0,0,w,h);pc.restore();pc.strokeStyle='rgba(240,255,255,.75)';pc.lineWidth=1;for(const p of particles){const geo=inverse(p.x,p.y),wind=geo&&sample(geo.lat,geo.lon);p.life-=dt;if(!wind||wind.speed<.5||p.life<=0){p.x=Math.random()*w;p.y=Math.random()*h;p.life=1+Math.random()*2;continue}const q=project(geo.lat+.02*wind.v/wind.speed,geo.lon+.02*wind.u/(wind.speed*Math.max(.12,Math.cos(geo.lat*rad)))),base=project(geo.lat,geo.lon),vx=q[0]-base[0],vy=-(q[1]-base[1]),length=Math.hypot(vx,vy);if(length<1e-10)continue;const step=(16+wind.speed*.4)*dt,x=p.x+vx/length*step,y=p.y+vy/length*step;pc.strokeStyle="rgba(240,255,255,"+(.75*(wind.coverage??1))+")";pc.beginPath();pc.moveTo(p.x,p.y);pc.lineTo(x,y);pc.stroke();p.x=x;p.y=y}}
